(base/'SOURCE_ROWS.json').write_text(json.dumps({'file':str(target),'sha256':hashlib.sha256(target.read_bytes()).hexdigest(),'rows':source},ensure_ascii=False,indent=2)+'\n')
for r in [new1,new2]:(base/f'{r[1]}_提示词.txt').write_text(r[5]+'\n')
(base/'PLAN_CHECK.json').write_text(json.dumps({'input':['81-2A','81-3A','81-4A'],'output':['81-2A','81-2B'],'seconds':[30,18],'shots':[len(first),len(second)],'walking_shot':{'storyboard':'81-2A','interval':[18,26],'seconds':8,'continuous':True,'hard_cuts_inside':0,'path':'茶几西南侧→南侧空道→茶几东南角→东窗内侧向北→东北转角内半步处'},'end_start_state':end,'speech_count':0,'source_text_preserved':True,'video_validation':'未实测'},ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'storyboards':2,'seconds':[30,18],'walking_interval':'18—26秒，一镜到底','rows_before':len(rows),'rows_after':len(out)},ensure_ascii=False))
